// ---- vectors generated by Node with shared/contract.ts canonicalJson (scripts/gen-chaincode-testdata.mjs)
type vec struct {
	PublicKeyHex string `json:"publicKeyHex"`
	Canonical    string `json:"canonical"`
	SignatureHex string `json:"signatureHex"`
}

func vectors(t *testing.T) map[string]vec {
	t.Helper()
	raw, err := os.ReadFile("../testdata/signatures.json")
	if err != nil {
		t.Fatal(err)
	}
	var m map[string]json.RawMessage
	_ = json.Unmarshal(raw, &m)
	out := map[string]vec{}
	for k, v := range m {
		var x vec
		if json.Unmarshal(v, &x) == nil && x.Canonical != "" {
			out[k] = x
		}
	}
	return out
}

const (
	sscc    = "089012340000004517"
	ref     = "WB-PSM-KGP2-POT-FPO07-2026-R-00451"
	token   = "FT-9c2e41a07b55d3f1"
	plot    = "PL-7Q2M9X4K1A"
	hash64  = "0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef"
	hash64b = "fedcba9876543210fedcba9876543210fedcba9876543210fedcba9876543210"
)

type env struct {
	t *testing.T
	l *testkit.Ledger
	c *LotContract
	v map[string]vec
}

func newEnv(t *testing.T) *env {
	return &env{t: t, l: testkit.NewLedger(), c: &LotContract{}, v: vectors(t)}
}

func (e *env) fpo(role string) *testkit.Ctx   { return e.l.As(cc.FpoOrg, role) }
func (e *env) buyer(role string) *testkit.Ctx { return e.l.As(cc.BuyerOrg, role) }

func (e *env) must(err error) {
	e.t.Helper()
	if err != nil {
		e.t.Fatalf("unexpected error: %v", err)
	}
}
func (e *env) wantCode(err error, code string) {
	e.t.Helper()
	if cc.CodeOf(err) != code {
		e.t.Fatalf("want %s, got %v", code, err)
	}
}
func (e *env) lot() *Lot {
	e.t.Helper()
	l, err := e.c.GetLot(e.fpo(""), sscc)
	e.must(err)
	return l
}
func (e *env) event() cc.EventPayload {
	ev, ok := e.l.LastEvent()
	if !ok {
		e.t.Fatal("no event")
	}
	var p cc.EventPayload
	e.must(json.Unmarshal(ev.Payload, &p))
	return p
}

func (e *env) registerFarmer() {
	e.must(e.c.RegisterFarmerAndPlot(e.fpo(cc.RoleVLE), token, e.v["f2"].PublicKeyHex, hash64, plot, hash64b))
}
func (e *env) registerDevices() {
	ceo := func() *testkit.Ctx { return e.fpo(cc.RoleCEO) }
	e.must(e.c.RegisterDevice(ceo(), "WB-CHG-01", e.v["weighbridge"].PublicKeyHex, "weighbridge"))
	e.must(e.c.RegisterDevice(ceo(), "QM-CHG-01", e.v["qualityPotato"].PublicKeyHex, "quality"))
}
func (e *env) commission() {
	e.must(e.c.CommissionLot(e.fpo(cc.RoleVLE), sscc, ref, token, plot, "POTATO", "Kufri Jyoti", "CHANGUAL", 40, 2000, "2026-11-02", e.v["f2"].SignatureHex))
}
func (e *env) grade() {
	e.must(e.c.AttestQuality(e.fpo(cc.RoleOperator), sscc, e.v["weighbridge"].Canonical, e.v["weighbridge"].SignatureHex, e.v["qualityPotato"].Canonical, e.v["qualityPotato"].SignatureHex, "A"))
}

// bring the lot to a status using the real functions
func (e *env) to(status string) {
	e.registerFarmer()
	e.registerDevices()
	e.commission()
	steps := []struct {
		st string
		fn func()
	}{
		{StGraded, e.grade},
		{StInStorage, func() { e.must(e.c.SetInStorage(e.fpo(cc.RoleWarehouse), sscc, "COLD_STORAGE", "DEP-2026-00201")) }},
		{StListed, func() { e.must(e.c.SetListed(e.fpo(cc.RoleCEO), sscc, "ORD-2026-00087")) }},
		{StSold, func() { e.must(e.c.SetSold(e.fpo(cc.RoleCEO), sscc, "ORD-2026-00087", hash64)) }},
		{StInTransit, func() { e.must(e.c.ProposeTransfer(e.fpo(cc.RoleOperator), sscc, cc.BuyerOrg, "WB74A1234", "BLE-01")) }},
		{StDelivered, func() { e.must(e.c.AcceptTransfer(e.buyer(cc.RoleBuyerManager), sscc)) }},
	}
	if status == StCommissioned {
		return
	}
	for _, s := range steps {
		s.fn()
		if s.st == status {
			return
		}
	}
	e.t.Fatalf("unknown status %s", status)
}

// ---------------------------------------------------------------- F1

func TestF1RegisterFarmerAndPlot(t *testing.T) {
	e := newEnv(t)
	e.must(e.c.RegisterFarmerAndPlot(e.fpo(cc.RoleVLE), token, e.v["f2"].PublicKeyHex, hash64, plot, hash64b))
	p := e.event()
	if p.EventType != "FarmerOnboarded" || strings.Join(p.AlsoEmitted, ",") != "PlotRegistered,ConsentGranted" || len(p.EPCList) != 0 {
		t.Errorf("event %+v", p)
	}
	f, err := e.c.GetFarmer(e.fpo(""), token)
	e.must(err)
	if f.DevicePubKeyHex != e.v["f2"].PublicKeyHex || len(f.PlotIDs) != 1 || f.Erased {
		t.Errorf("farmer %+v", f)
	}
	// second plot for the same farmer only registers the plot
	e.must(e.c.RegisterFarmerAndPlot(e.fpo(cc.RoleVLE), token, "", hash64, "PL-AAAAAAAAAA", hash64b))
	if e.event().EventType != "PlotRegistered" {
		t.Error("second plot must emit PlotRegistered")
	}
	f, _ = e.c.GetFarmer(e.fpo(""), token)
	if len(f.PlotIDs) != 2 || len(f.PolygonHashes) != 2 {
		t.Errorf("plots %+v", f.PlotIDs)
	}
	e.wantCode(e.c.RegisterFarmerAndPlot(e.fpo(cc.RoleVLE), token, "", hash64, plot, hash64b), cc.ErrInvalidState)
}

func TestF1Validation(t *testing.T) {
	e := newEnv(t)
	e.wantCode(e.c.RegisterFarmerAndPlot(e.fpo(cc.RoleMember), token, "", hash64, plot, hash64b), cc.ErrForbiddenRole)
	e.wantCode(e.c.RegisterFarmerAndPlot(e.l.As(cc.BankOrg, cc.RoleVLE), token, "", hash64, plot, hash64b), cc.ErrForbiddenOrg)
	e.wantCode(e.c.RegisterFarmerAndPlot(e.fpo(cc.RoleVLE), "FT-xyz", "", hash64, plot, hash64b), cc.ErrValidation)
	e.wantCode(e.c.RegisterFarmerAndPlot(e.fpo(cc.RoleVLE), token, "", "short", plot, hash64b), cc.ErrValidation)
	e.wantCode(e.c.RegisterFarmerAndPlot(e.fpo(cc.RoleVLE), token, "04"+strings.Repeat("11", 64), hash64, plot, hash64b), cc.ErrValidation)
	_, err := e.c.GetFarmer(e.fpo(""), token)
	e.wantCode(err, cc.ErrNotFound)
}

func TestDeviceKeyRegistration(t *testing.T) {
	e := newEnv(t)
	e.must(e.c.RegisterFarmerAndPlot(e.fpo(cc.RoleVLE), token, "", hash64, plot, hash64b))
	e.wantCode(e.c.RegisterDeviceKey(e.fpo(cc.RoleMember), "FT-0000000000000000", e.v["f2"].PublicKeyHex), cc.ErrNotFound)
	e.wantCode(e.c.RegisterDeviceKey(e.fpo(cc.RoleMember), token, "zz"), cc.ErrValidation)
	e.must(e.c.RegisterDeviceKey(e.fpo(cc.RoleMember), token, e.v["f2"].PublicKeyHex))
	f, _ := e.c.GetFarmer(e.fpo(""), token)
	if f.DevicePubKeyHex == "" {
		t.Error("key not stored")
	}
	e.wantCode(e.c.RegisterDeviceKey(e.l.As(cc.BuyerOrg, cc.RoleBuyerManager), token, e.v["f2"].PublicKeyHex), cc.ErrForbiddenOrg)
}

func TestRegisterDeviceRules(t *testing.T) {
	e := newEnv(t)
	k := e.v["weighbridge"].PublicKeyHex
	e.wantCode(e.c.RegisterDevice(e.fpo(cc.RoleOperator), "WB-CHG-01", k, "weighbridge"), cc.ErrForbiddenRole)
	e.wantCode(e.c.RegisterDevice(e.fpo(cc.RoleCEO), "WB-CHG-01", k, "scale"), cc.ErrValidation)
	e.wantCode(e.c.RegisterDevice(e.fpo(cc.RoleCEO), "", k, "weighbridge"), cc.ErrValidation)
	e.wantCode(e.c.RegisterDevice(e.fpo(cc.RoleCEO), "WB-CHG-01", "04ab", "weighbridge"), cc.ErrValidation)
	e.must(e.c.RegisterDevice(e.fpo(cc.RoleCEO), "WB-CHG-01", k, "weighbridge"))
	d, err := e.c.GetDevice(e.fpo(""), "WB-CHG-01")
	e.must(err)
	if d.Kind != "weighbridge" {
		t.Error(d)
	}
	_, err = e.c.GetDevice(e.fpo(""), "nope")
	e.wantCode(err, cc.ErrNotFound)
}

func TestInputEventAnchorsHashOnly(t *testing.T) {
	e := newEnv(t)
	e.registerFarmer()
	e.must(e.c.RecordInputEvent(e.fpo(cc.RoleMember), token, hash64, "POTATO", "2026-10-05", "2026-10-12"))
	p := e.event()
	if p.EventType != "InputApplied" || p.Refs["inputHash"] != hash64 {
		t.Errorf("%+v", p)
	}
	e.wantCode(e.c.RecordInputEvent(e.fpo(cc.RoleMember), token, "nothex", "POTATO", "", ""), cc.ErrValidation)
	e.wantCode(e.c.RecordInputEvent(e.fpo(cc.RoleMember), "FT-0000000000000000", hash64, "POTATO", "", ""), cc.ErrNotFound)
	e.wantCode(e.c.RecordInputEvent(e.l.As(cc.BankOrg, cc.RoleCreditOfficer), token, hash64, "POTATO", "", ""), cc.ErrForbiddenOrg)
}

