func TestF2CommissionWithValidFarmerSignature(t *testing.T) {
	e := newEnv(t)
	e.registerFarmer()
	e.commission()
	l := e.lot()
	if l.Status != StCommissioned || l.OriginStatus != OriginVerified || l.FarmerToken != token || l.HumanRef != ref || l.BagCount != 40 {
		t.Errorf("%+v", l)
	}
	if p := e.event(); p.EventType != "LotCommissioned" || p.EPCList[0] != sscc || p.BizStep != "urn:epcglobal:cbv:bizstep:commissioning" {
		t.Errorf("%+v", p)
	}
	lots, err := e.c.ListLotsByFarmer(e.fpo(""), token)
	e.must(err)
	if len(lots) != 1 || lots[0] != sscc {
		t.Errorf("index %v", lots)
	}
}

func TestF2RejectsBadFarmerSignature(t *testing.T) {
	e := newEnv(t)
	e.registerFarmer()
	sig := e.v["f2"].SignatureHex
	cases := map[string]func() error{
		"bagCount changed after signing": func() error {
			return e.c.CommissionLot(e.fpo(cc.RoleVLE), sscc, ref, token, plot, "POTATO", "x", "CHANGUAL", 41, 2000, "2026-11-02", sig)
		},
		"weight changed": func() error {
			return e.c.CommissionLot(e.fpo(cc.RoleVLE), sscc, ref, token, plot, "POTATO", "x", "CHANGUAL", 40, 2100, "2026-11-02", sig)
		},
		"date changed": func() error {
			return e.c.CommissionLot(e.fpo(cc.RoleVLE), sscc, ref, token, plot, "POTATO", "x", "CHANGUAL", 40, 2000, "2026-11-03", sig)
		},
		"signature of another key": func() error {
			return e.c.CommissionLot(e.fpo(cc.RoleVLE), sscc, ref, token, plot, "POTATO", "x", "CHANGUAL", 40, 2000, "2026-11-02", e.v["weighbridge"].SignatureHex)
		},
		"empty signature": func() error {
			return e.c.CommissionLot(e.fpo(cc.RoleVLE), sscc, ref, token, plot, "POTATO", "x", "CHANGUAL", 40, 2000, "2026-11-02", "")
		},
	}
	for name, run := range cases {
		if err := run(); cc.CodeOf(err) != cc.ErrBadFarmerSignature {
			t.Errorf("%s: want ERR_BAD_FARMER_SIGNATURE, got %v", name, err)
		}
	}
	if _, err := e.c.GetLot(e.fpo(""), sscc); cc.CodeOf(err) != cc.ErrNotFound {
		t.Error("no lot may exist after a rejected commission")
	}
}

func TestF2OtherRules(t *testing.T) {
	e := newEnv(t)
	sig := e.v["f2"].SignatureHex
	args := func(c *testkit.Ctx) error {
		return e.c.CommissionLot(c, sscc, ref, token, plot, "POTATO", "x", "CHANGUAL", 40, 2000, "2026-11-02", sig)
	}
	e.wantCode(args(e.fpo(cc.RoleMember)), cc.ErrForbiddenRole)
	e.wantCode(args(e.l.As(cc.BuyerOrg, cc.RoleVLE)), cc.ErrForbiddenOrg)
	e.wantCode(args(e.fpo(cc.RoleVLE)), cc.ErrNotFound) // farmer not registered
	e.must(e.c.RegisterFarmerAndPlot(e.fpo(cc.RoleVLE), token, "", hash64, plot, hash64b))
	e.wantCode(args(e.fpo(cc.RoleVLE)), cc.ErrBadFarmerSignature) // no device key yet
	e.must(e.c.RegisterDeviceKey(e.fpo(cc.RoleMember), token, e.v["f2"].PublicKeyHex))
	e.wantCode(e.c.CommissionLot(e.fpo(cc.RoleVLE), sscc, ref, token, "PL-ZZZZZZZZZZ", "POTATO", "x", "CHANGUAL", 40, 2000, "2026-11-02", sig), cc.ErrValidation)
	e.wantCode(e.c.CommissionLot(e.fpo(cc.RoleVLE), "089012340000004518", ref, token, plot, "POTATO", "x", "CHANGUAL", 40, 2000, "2026-11-02", sig), cc.ErrValidation)
	e.wantCode(e.c.CommissionLot(e.fpo(cc.RoleVLE), sscc, "bad-ref", token, plot, "POTATO", "x", "CHANGUAL", 40, 2000, "2026-11-02", sig), cc.ErrValidation)
	e.wantCode(e.c.CommissionLot(e.fpo(cc.RoleVLE), sscc, ref, token, plot, "MANGO", "x", "CHANGUAL", 40, 2000, "2026-11-02", sig), cc.ErrValidation)
	e.wantCode(e.c.CommissionLot(e.fpo(cc.RoleVLE), sscc, ref, token, plot, "POTATO", "x", "ATLANTIS", 40, 2000, "2026-11-02", sig), cc.ErrValidation)
	e.wantCode(e.c.CommissionLot(e.fpo(cc.RoleVLE), sscc, ref, token, plot, "POTATO", "x", "CHANGUAL", 0, 2000, "2026-11-02", sig), cc.ErrValidation)
	e.must(args(e.fpo(cc.RoleOperator)))                    // operators may commission too
	e.wantCode(args(e.fpo(cc.RoleVLE)), cc.ErrInvalidState) // duplicate
}

func TestF2BengaliAndGoVerifiesNodeBytes(t *testing.T) {
	e := newEnv(t)
	v := e.v["f2Bengali"]
	var m map[string]any
	e.must(json.Unmarshal([]byte(v.Canonical), &m))
	got, err := cc.CanonicalValue(m)
	e.must(err)
	if string(got) != v.Canonical {
		t.Fatalf("canonical bytes differ:\n%s\n%s", got, v.Canonical)
	}
	e.must(cc.VerifyP256(v.PublicKeyHex, v.SignatureHex, got))
}

